create or replace function public.check_permission_audited(target_permission text,target_organisation uuid default null)returns boolean language plpgsql security definer set search_path=public as $$declare allowed boolean;begin allowed:=has_permission(target_permission,target_organisation);if not allowed then insert into audit_logs(actor_id,entity_type,entity_id,action,after_data)values(auth.uid(),'permission',coalesce(target_organisation::text,'platform'),'permission_denied',jsonb_build_object('permission',target_permission,'organisation_id',target_organisation));end if;return allowed;end;$$;
revoke all on function public.check_permission_audited(text,uuid)from public,anon;grant execute on function public.check_permission_audited(text,uuid)to authenticated;
drop policy if exists "customer payment read"on public.payments;create policy "customer payment read"on public.payments for select using(exists(select 1 from orders o where o.id=order_id and customer_can_read_order(o)));
drop policy if exists "supplier payment read"on public.payments;create policy "supplier payment read"on public.payments for select using(exists(select 1 from orders o where o.id=order_id and has_permission('finance.view',o.supplier_id)));
drop policy if exists "delivery customer read"on public.deliveries;create policy "delivery customer read"on public.deliveries for select using(exists(select 1 from orders o where o.id=order_id and customer_can_read_order(o)));
drop policy if exists "delivery supplier read"on public.deliveries;create policy "delivery supplier read"on public.deliveries for select using(exists(select 1 from orders o where o.id=order_id and has_permission('deliveries.view',o.supplier_id)));
drop policy if exists "delivery proof participant read"on storage.objects;create policy "delivery proof participant read"on storage.objects for select to authenticated using(bucket_id='delivery-proofs'and exists(select 1 from deliveries d join orders o on o.id=d.order_id where d.id=((storage.foldername(name))[1])::uuid and(d.driver_id=auth.uid()or customer_can_read_order(o)or has_permission('deliveries.view',o.supplier_id)or is_platform_admin())));
create or replace function public.customer_cancel_order(target_order uuid)returns void language plpgsql security definer set search_path=public as $$begin update orders set status='cancelled',updated_at=now()where id=target_order and(customer_id=auth.uid()or(customer_organisation_id is not null and has_permission('orders.approve',customer_organisation_id)))and status='awaiting_payment';if not found then raise exception 'Order cannot be cancelled';end if;end;$$;
create or replace function public.customer_confirm_delivery(target_order uuid)returns void language plpgsql security definer set search_path=public as $$begin update orders set status='completed',updated_at=now()where id=target_order and(customer_id=auth.uid()or(customer_organisation_id is not null and has_permission('orders.approve',customer_organisation_id)))and status='customer_confirmation_pending';if not found then raise exception 'Order is not awaiting confirmation';end if;end;$$;
create or replace function public.customer_open_dispute(target_order uuid,target_reason text)returns uuid language plpgsql security definer set search_path=public as $$declare result uuid;order_row orders;begin if length(trim(target_reason))<10 then raise exception 'Provide dispute details';end if;select * into order_row from orders where id=target_order for update;if order_row.id is null or not(order_row.customer_id=auth.uid()or(order_row.customer_organisation_id is not null and has_permission('orders.approve',order_row.customer_organisation_id)))or order_row.status not in('customer_confirmation_pending','completed')then raise exception 'Order cannot be disputed';end if;update orders set status='disputed',updated_at=now()where id=target_order;insert into order_disputes(order_id,customer_id,reason)values(target_order,auth.uid(),trim(target_reason))returning id into result;return result;end;$$;
